import re

def parse_duration(s):
  """
  Converts strings like '1h30m', '45s', '2h5s' or '3m' into a total number of seconds (int).
  Returns only the code in one ```python block.
  """
  match = re.match(r'(\d+)h(\d+)m', s)
  if match:
    return int(match.group(1)) + int(match.group(2))
  else:
    return 0
